// 5. Ovládanie - Tlačidlo SKOK
button.visible = true;
button.text = "ŠTART / SKOK!"; 
button.color = "#ff4757";
button.width = 300;
button.height = 80;
button.x = 0;    // Stred obrazovky
button.y = 250;  // Umiestnené bezpečne dole

// Herná fyzika a pamäť
let rychlostSkoku = 0;
let gravitacia = 1.5; // Nižšia gravitácia = ľahší a dlhší skok
let hracNaZemi = true;
let skore = 0;
let hraBezi = false;
let rychlostHry = 14; // Všetci idú rovnakou rýchlosťou!

// Reakcia na tlačidlo SKOK
button.onClick = function() {
    if (!hraBezi) {
        // Nová hra
        hraBezi = true;
        skore = 0;
        status.text("SKÓRE: 0");
        creeper.y = 200;
        
        // Zrovnáme ich pekne za sebou s rozostupom 600px
        box.x = 800;
        goomby[0].x = 1400;
        goomby[1].x = 2000;
        
        creeper.eyes = true;
        creeper.mouth = true;
        button.text = "SKOK!";
    } else if (hracNaZemi) {
        // Výskok
        rychlostSkoku = -28; 
        hracNaZemi = false;
        creeper.legs = !creeper.legs; 
    }
};

// 6. HLAVNÝ MOTOR HRY
if (typeof staraHra !== 'undefined') clearInterval(staraHra);

window.staraHra = setInterval(function() {
    if (!hraBezi) return; 

    // --- A) GRAVITÁCIA A SKÁKANIE ---
    creeper.y = creeper.y + rychlostSkoku;
    rychlostSkoku = rychlostSkoku + gravitacia; 
    
    if (creeper.y > 200) {
        creeper.y = 200;
        rychlostSkoku = 0;
        hracNaZemi = true;
    }

    // --- B) POHYB PREKÁŽOK A NEPRIATEĽOV ---
    
    // Trúbka
    box.x = box.x - rychlostHry; 
    if (box.x < -600) {
        // Zaradí sa bezpečne na koniec radu (k aktuálnej pozícii + 1800)
        box.x = box.x + 1800; 
        skore = skore + 1; 
        status.text("SKÓRE: " + skore);
    }
    
    // Goomby
    for (let i = 0; i < goomby.length; i++) {
        goomby[i].x = goomby[i].x - rychlostHry; 
        
        if (Math.round(goomby[i].x / 20) % 2 === 0) {
            goomby[i].legs = !goomby[i].legs;
        }

        if (goomby[i].x < -600) {
            goomby[i].x = goomby[i].x + 1800; // Zaradí sa na koniec radu
            skore = skore + 1; 
            status.text("SKÓRE: " + skore);
        }
    }
    
    // --- C) MATEMATIKA NÁRAZOV (Kolízie) ---
    function dotyk(obj1, obj2) {
        let vzdialenostX = Math.abs(obj1.x - obj2.x);
        let vzdialenostY = Math.abs(obj1.y - obj2.y);
        
        let sirkaSpolu = (obj1.width / 2) + (obj2.width / 2) - 15; 
        let vyskaSpolu = (obj1.height / 2) + (obj2.height / 2) - 15;
        
        return (vzdialenostX < sirkaSpolu) && (vzdialenostY < vyskaSpolu);
    }
    
    if (dotyk(creeper, box)) {
        hraBezi = false;
        status.text("💥 AU! NÁRAZ DO TRÚBKY! Skóre: " + skore);
        creeper.eyes = false; creeper.mouth = false;
        button.text = "ŠTART ZNOVA";
    }
    
    for (let i = 0; i < goomby.length; i++) {
        if (dotyk(creeper, goomby[i])) {
            
            // ŠPECIÁLNY TRIK: Zásah zhora!
            if (rychlostSkoku > 0 && creeper.y < goomby[i].y - 30) {
                goomby[i].x = goomby[i].x + 1800; // Pošleme ju na koniec radu
                rychlostSkoku = -25; // Mário sa odrazí!
                skore = skore + 5;   
                status.text("SKÓRE: " + skore);
            } else {
                hraBezi = false;
                status.text("😵 POHRÝZLA ŤA GOOMBA! Skóre: " + skore);
                creeper.eyes = false; creeper.mouth = false;
                button.text = "ŠTART ZNOVA";
            }
        }
    }

}, 30);
